import java.io.DataInputStream;
import java.io.IOException;
import java.io.PrintWriter;

public class Solution {
    static final long MOD = 998244353L;

    static class FastScanner {
        private final DataInputStream in = new DataInputStream(System.in);

        long nextLong() throws IOException {
            int c = in.read();
            while (c <= ' ' && c != -1) {
                c = in.read();
            }
            if (c == -1) {
                throw new IOException("EOF");
            }
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = in.read();
            }
            long value = 0;
            while (c > ' ') {
                value = value * 10 - (c - '0');
                c = in.read();
            }
            if (negative) {
                return value;
            }
            if (value == Long.MIN_VALUE) {
                throw new NumberFormatException();
            }
            return -value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        long n = fs.nextLong();
        long m = fs.nextLong();
        long l = fs.nextLong();
        long r = fs.nextLong();

        long prod = n * m;

        if ((prod & 1) == 1) {
            out.println(exp(r - l + 1, prod));
            out.close();
            return;
        }

        long E = r / 2 - (l - 1) / 2;
        long O = r - l + 1 - E;

        long ans = (exp(E + O, prod) + exp(E - O, prod)) % MOD;
        ans = (ans * exp(2, MOD - 2)) % MOD;

        out.println(ans);
        out.close();
    }

    static long exp(long base, long exponent) {
        long result = 1L;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exponent >>= 1;
        }
        return result;
    }
}
